#include <stdio.h>
#include <stdlib.h>

// Define the maximum number of nodes
#define MAX_NODES 8

// Function to perform topological sorting
void topological_sort(int adj[][MAX_NODES], int indegree[], int done[], int nodes) {
    int stack[MAX_NODES];
    int top = -1;
    int i, j;

    // Initialize the stack and done array
    for (i = 0; i < nodes; i++) {
        if (indegree[i] == 0) {
            stack[++top] = i;
        }
    }

    // Perform the topological sorting
    while (top != -1) {
        int node = stack[top--];
        printf("%d ", node);
        done[node] = 1;

        for (j = 0; j < nodes; j++) {
            if (adj[node][j] == 1 && indegree[j] > 0) {
                indegree[j]--;
                if (indegree[j] == 0) {
                    stack[++top] = j;
                }
            }
        }
    }
}

int main(int argc, char *argv[]) {
    int adj[MAX_NODES][MAX_NODES] = {{0}};
    int indegree[MAX_NODES] = {0};
    int done[MAX_NODES] = {0};
    int nodes = 0;
    int i, j;

    // Read the number of nodes from the command line
    if (argc > 1) {
        nodes = atoi(argv[1]);
    }

    // Read the adjacency matrix from the command line
    for (i = 2; i < argc; i += 2) {
        int u = atoi(argv[i]);
        int v = atoi(argv[i + 1]);
        adj[u][v] = 1;
        indegree[v]++;
    }

    // Perform the topological sorting
    topological_sort(adj, indegree, done, nodes);

    // Check for cycles
    for (i = 0; i < nodes; i++) {
        if (done[i] == 0) {
            printf("CYCLE\n");
            return 1;
        }
    }

    return 0;
}
